mapper.select:
SELECT share_id, note_id, note_version, author_id, share_time, expire_time,
access_type, access_password, share_token, is_active, access_count
FROM note_shares
WHERE author_id = #{authorId}
ORDER BY share_time DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE note_shares
SET is_active = #{isActive}
WHERE share_id = #{shareId}

UPDATE note_shares
SET access_count = access_count + 1
WHERE share_id = #{shareId}

mapper.select:
SELECT COUNT(*)
FROM note_shares
WHERE author_id = #{authorId}
